  "title": "Relative change formula",
  "problem": "A concert ticket increased from an initial value of $80 to a final value of $100. Calculate the percent change using formal relative change.",
  "steps": [
    {
      "text": "Calculate absolute change, defined as final value minus initial value.",
      "math": "\\Delta V = V_{\\text{final}} - V_{\\text{initial}} = 100 - 80 = 20"
    },
    {
      "text": "Compute relative change by dividing by the initial baseline, never the new price.",
      "math": "\\frac{\\Delta V}{V_{\\text{initial}}} = \\frac{20}{80} = 0.25"
    },
    {
      "text": "Scale by 100 to express the relative shift as a signed percentage.",
      "math": "0.25 \\times 100\\% = +25\\%"
    }
  ],
  "result": "The price saw a +25% change relative to the initial $80 base.",
  "image": null
}

